// Local authority IDs to watch (from https://api.ratings.food.gov.uk/Authorities/basic).
// Newham 112, Hackney 99, Southwark 115, Chelmsford 10, Birmingham 374. Add as many as you like.
const authorities = [112, 99, 115, 10, 374];
const ratings = ['0', '1', '2'];
const out = [];
for (const la of authorities) {
  for (const r of ratings) {
    out.push({ json: { url: `https://api.ratings.food.gov.uk/Establishments?localAuthorityId=${la}&ratingKey=${r}&schemeTypeKey=FHRS&pageSize=5000&pageNumber=1`, la, r } });
  }
}
return out;

// Flatten every establishment, then keep only ones we have not seen before at this RatingDate.
// Seen-set lives in workflow static data, so no database is needed to start.
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const out = [];
for (const item of $input.all()) {
  const list = (item.json.establishments || []);
  for (const e of list) {
    const key = `${e.FHRSID}:${(e.RatingDate || '').slice(0, 10)}`;
    if (staticData.seen[key]) continue;
    staticData.seen[key] = 1;
    out.push({ json: {
      fhrsid: e.FHRSID,
      name: e.BusinessName,
      type: e.BusinessType,
      address: [e.AddressLine1, e.AddressLine2, e.AddressLine3, e.AddressLine4, e.PostCode].filter(Boolean).join(', '),
      postcode: e.PostCode,
      authority: e.LocalAuthorityName,
      rating: e.RatingValue,
      rating_date: (e.RatingDate || '').slice(0, 10),
      hygiene: e.scores && e.scores.Hygiene,
      structural: e.scores && e.scores.Structural,
      confidence: e.scores && e.scores.ConfidenceInManagement,
      pending: e.NewRatingPending,
      right_to_reply: e.RightToReply || '',
      fsa_url: `https://ratings.food.gov.uk/business/${e.FHRSID}`
    } });
  }
}
// Newest inspections first; on the very first run this will be the whole backlog, which is useful as the initial outreach list.
out.sort((a, b) => (b.json.rating_date || '').localeCompare(a.json.rating_date || ''));
return out;

